77 |     /// Removes the last element from the list.
78 |     pub fn pop(&mut self) -> Option<T> {
79 |         match self.inner.back_mut() {
80 |             Some(last) => {
81 |                 if last.is_empty() {
82 |                     self.inner.pop_back();
83 |                     self.pop()
84 |                 } else {
85 |                     self.len -= 1;
86 |                     last.pop()
87 |                 }
88 |             }
89 |             None => None,
90 |         }
91 |     }

